import{_ as t,a as n,o,a2 as s}from"./chunks/framework.DCcmcJcL.js";const d=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"configure/about.md","filePath":"configure/about.md","lastUpdated":1789395222000}'),r={name:"configure/about.md"};function a(i,e,g,h,l,c){return o(),n("div",null,e[0]||(e[0]=[s('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>The <strong>About</strong> screen shows what your store runs on and which services it uses. There is nothing to change here. Open it when support asks which version you are on, or to confirm that a setting made elsewhere has taken effect. The <strong>About</strong> group is available in Bagisto 2.5.</p><p>Go to <strong>Configure &gt;&gt; About &gt;&gt; General</strong>. The screen is grouped into cards:</p><ul><li><strong>Bagisto</strong> – the Bagisto version.</li><li><strong>Environment</strong> – the application name, the Laravel, PHP and Composer versions, the store URL, the environment (<strong>Local</strong>, <strong>Staging</strong>, <strong>Testing</strong> or <strong>Production</strong>), whether <strong>Debug Mode</strong> is on, the timezone, the locale, and whether maintenance mode is on.</li><li><strong>Database</strong> – the database engine and its version.</li><li><strong>Drivers</strong> – the services that handle the cache, sessions, the queue and logging.</li><li><strong>Mail</strong> – the transport email is sent through, as set under <a href="./email-settings.html">Email Settings</a>.</li><li><strong>Search</strong> – the search engine in use, as set under <a href="./search-engines.html">Search Engines</a>.</li><li><strong>Storage</strong> – the storage in use and whether its public link exists, as set under <a href="./file-management.html">File Management</a>.</li><li><strong>Cached</strong> – whether the configuration, routes, events and views are cached. Clear or build them under <a href="./cache-management.html">Cache Management</a>.</li></ul><p>If this screen shows <strong>Debug Mode</strong> on while the environment is <strong>Production</strong>, ask whoever manages the server to turn debug mode off, because it can show technical details to visitors when something goes wrong.</p>',5)]))}const m=t(r,[["render",a]]);export{d as __pageData,m as default};
